def collapse_ints(nums: list[int]) -> str:
    """Sort distinct ints; write runs of 4+ consecutive as first-last.

    A negative endpoint inside a range is written in parentheses;
    outside a range numbers are written plainly.
    """
    uniq = sorted(set(nums))
    if not uniq:
        return ""
    parts: list[str] = []
    i = 0
    n = len(uniq)
    while i < n:
        j = i
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            a, b = uniq[i], uniq[j]
            sa = f"({a})" if a < 0 else str(a)
            sb = f"({b})" if b < 0 else str(b)
            parts.append(f"{sa}-{sb}")
        else:
            for k in range(i, j + 1):
                parts.append(str(uniq[k]))
        i = j + 1
    return ",".join(parts)

